package ledger

import (
	"fmt"
	"sort"
	"strings"
)

// Entry represents a single ledger entry.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// FormatLedger formats a ledger in the given locale and currency.
// Entries are sorted by date, then description, then change.
func FormatLedger(currency, locale string, entries []Entry) (string, error) {
	// Validate parameters up front so that even an empty ledger
	// with a bad currency or locale fails.
	if currency != "USD" && currency != "EUR" {
		return "", fmt.Errorf("invalid currency %q", currency)
	}
	cfg, ok := locales[locale]
	if !ok {
		return "", fmt.Errorf("invalid locale %q", locale)
	}

	// Work on a copy so the caller's slice is never modified.
	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(cfg.header)
	for _, e := range sorted {
		line, err := formatLine(cfg, currency, e)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}
```

