// formatDescription fits a description into the description column,
// truncating overlong values with an ellipsis.
func formatDescription(description string) string {
	if len(description) > descriptionColumnWidth {
		return description[:descriptionColumnWidth-3] + "..."
	}
	return description + strings.Repeat(" ", descriptionColumnWidth-len(description))
}

// formatNumber renders the absolute value of a cent amount with the given
// thousands and decimal separators, e.g. 12345 with "." and "," becomes
// "123,45".
func formatNumber(cents int, thousandsSep, decimalSep string) string {
	if cents < 0 {
		cents = -cents
	}
	digits := strconv.Itoa(cents)
	for len(digits) < 3 {
		digits = "0" + digits
	}
	whole, fraction := digits[:len(digits)-2], digits[len(digits)-2:]
	return groupDigits(whole, thousandsSep) + decimalSep + fraction
}

// groupDigits inserts a separator every three digits from the right,
// e.g. groupDigits("123456", ",") == "123,456".
func groupDigits(digits, sep string) string {
	var b strings.Builder
	for i, r := range digits {
		if i > 0 && (len(digits)-i)%3 == 0 {
			b.WriteString(sep)
		}
		b.WriteRune(r)
	}
	return b.String()
}

